<?php
require __DIR__.'/_layout.php';$u=require_admin();$pdo=db();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{csrf_check();$a=$_POST['action']??'';
  if($a==='create_schedule'){
   $title=trim((string)($_POST['title']??''));$type='ENSAIO';$weekday=(int)($_POST['weekday']??0);$start=trim((string)($_POST['start_time']??''));$end=trim((string)($_POST['end_time']??''));$notes=trim((string)($_POST['notes']??''));$areas=array_values(array_intersect(enrollment_instruments(),array_map('strval',$_POST['areas']??[])));$incStudents=isset($_POST['include_students'])?1:0;$incInstructors=isset($_POST['include_instructors'])?1:0;$incTeam=isset($_POST['include_team'])?1:0;$incCompanions=isset($_POST['include_companions'])?1:0;
   if(!in_array($title,bamab_rehearsal_names(),true))throw new RuntimeException('Selecione uma opção válida de ensaio.');if(!isset(bamab_weekdays()[$weekday]))throw new RuntimeException('Selecione um dia da semana.');if(!$areas)throw new RuntimeException('Selecione pelo menos uma ala participante.');
   if(!$incStudents&&!$incInstructors&&!$incTeam&&!$incCompanions)throw new RuntimeException('Selecione pelo menos um grupo para marcar presença.');$pdo->beginTransaction();$pdo->prepare("INSERT INTO attendance_schedules(title,event_type,weekday,start_time,end_time,notes,active,created_at,updated_at,created_by,include_students,include_instructors,include_team,include_companions) VALUES(?,?,?,?,?,?,1,?,?,?,?,?,?,?)")->execute([$title,$type,$weekday,$start,$end,$notes,now_iso(),now_iso(),(int)$u['id'],$incStudents,$incInstructors,$incTeam,$incCompanions]);$id=(int)$pdo->lastInsertId();$ia=$pdo->prepare("INSERT INTO attendance_schedule_areas(schedule_id,area) VALUES(?,?)");foreach($areas as $area)$ia->execute([$id,$area]);$pdo->commit();go('presenca.php','Programação semanal criada. A data será gerada automaticamente quando o instrutor entrar no dia escolhido.');
  }
  if($a==='toggle_schedule'){$id=(int)$_POST['schedule_id'];$active=(int)$_POST['active']===1?1:0;$pdo->prepare("UPDATE attendance_schedules SET active=?,updated_at=? WHERE id=?")->execute([$active,now_iso(),$id]);go('presenca.php',$active?'Programação ativada.':'Programação pausada.');}
  if($a==='delete_schedule'){if(!is_general_admin($u))throw new RuntimeException('Somente o Admin Geral pode excluir programações.');$id=(int)$_POST['schedule_id'];$st=$pdo->prepare("SELECT COUNT(*) FROM attendance_events WHERE schedule_id=?");$st->execute([$id]);if((int)$st->fetchColumn()>0)throw new RuntimeException('Esta programação já possui histórico de presença. Para preservar os relatórios, apenas desative-a.');$pdo->prepare("DELETE FROM attendance_schedules WHERE id=?")->execute([$id]);go('presenca.php','Programação excluída.');}
  if($a==='delete_all_reports'){
   if(!is_general_admin($u))throw new RuntimeException('Somente o Admin Geral pode excluir todos os relatórios.');
   $confirm=trim((string)($_POST['confirm_delete']??''));
   if($confirm!=='EXCLUIR TODOS')throw new RuntimeException('Digite EXCLUIR TODOS para confirmar.');
   $pdo->beginTransaction();
   try{
     $pdo->exec("DELETE FROM attendance_checks");
     $pdo->exec("DELETE FROM attendance_records");
     $pdo->exec("DELETE FROM attendance_area_controls");
     $pdo->exec("DELETE FROM attendance_general_controls");
     $pdo->exec("DELETE FROM attendance_event_areas");
     $pdo->exec("DELETE FROM attendance_events");
     $pdo->commit();
   }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
   go('presenca.php','Todos os relatórios/históricos de ensaios foram excluídos. A programação semanal e os cadastros foram preservados.');
  }
  if($a==='close'){$id=(int)$_POST['event_id'];$now=now_iso();$pdo->prepare("UPDATE attendance_events SET active=0,closed_at=? WHERE id=?")->execute([$now,$id]);$pdo->prepare("UPDATE attendance_general_controls SET phase='CONCLUIDO',exit_closed_at=COALESCE(exit_closed_at,?),last_admin_id=?,updated_at=? WHERE event_id=?")->execute([$now,(int)$u['id'],$now,$id]);go('presenca.php?event_id='.$id,'Controle do dia encerrado.');}
  if($a==='reset_area'){if(!is_general_admin($u))throw new RuntimeException('Somente Admin Geral.');$id=(int)$_POST['event_id'];$area=(string)$_POST['area'];$pdo->prepare("DELETE FROM attendance_checks WHERE event_id=? AND area=? AND person_type='ALUNO'")->execute([$id,$area]);$pdo->prepare("UPDATE attendance_area_controls SET phase='FECHADO',entry_opened_at=NULL,entry_closed_at=NULL,exit_opened_at=NULL,exit_closed_at=NULL,last_instructor_id=NULL,updated_at=? WHERE event_id=? AND area=?")->execute([now_iso(),$id,$area]);go('presenca.php?event_id='.$id,'Controle da ala reiniciado.');}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}
}
$days=bamab_weekdays();$schedules=$pdo->query("SELECT * FROM attendance_schedules ORDER BY weekday,start_time,title COLLATE NOCASE")->fetchAll();
$today=today_bamab_date();$todayWeek=today_bamab_weekday();$st=$pdo->prepare("SELECT ae.*,(SELECT COUNT(*) FROM attendance_checks ac WHERE ac.event_id=ae.id AND ac.check_type='ENTRADA') entries,(SELECT COUNT(*) FROM attendance_checks ac WHERE ac.event_id=ae.id AND ac.check_type='SAIDA') exits FROM attendance_events ae WHERE ae.event_date=? ORDER BY ae.start_time,ae.id");$st->execute([$today]);$todayEvents=$st->fetchAll();
$events=$pdo->query("SELECT ae.*,(SELECT COUNT(*) FROM attendance_checks ac WHERE ac.event_id=ae.id AND ac.check_type='ENTRADA') entries,(SELECT COUNT(*) FROM attendance_checks ac WHERE ac.event_id=ae.id AND ac.check_type='SAIDA') exits FROM attendance_events ae ORDER BY event_date DESC,id DESC LIMIT 100")->fetchAll();
$selectedId=(int)($_GET['event_id']??($todayEvents[0]['id']??($events[0]['id']??0)));$st=$pdo->prepare("SELECT * FROM attendance_events WHERE id=?");$st->execute([$selectedId]);$selected=$st->fetch()?:null;$selectedAreas=$selected?attendance_event_areas($selectedId):[];
admin_header('Presença por Ala — Programação Semanal');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
