<section class="panel"><div class="panel-heading-flex"><div><span>CONTROLE SIMPLIFICADO</span><h2>Ensaios por dia da semana</h2><p>Escolha o tipo de ensaio e o dia da semana. A data real é criada automaticamente quando o Professor/Instrutor entra naquele dia.</p></div></div><div class="today-date-admin"><span>HOJE</span><strong><?=e(bamab_weekday_label($todayWeek))?> · <?=e(date('d/m/Y'))?></strong></div></section>
<section class="panel"><h2>Criar programação semanal</h2><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_schedule"><div class="grid2"><label>Nome do ensaio<select name="title" required><option value="">SELECIONE</option><?php foreach(bamab_rehearsal_names() as $rn):?><option value="<?=e($rn)?>"><?=e($rn)?></option><?php endforeach;?></select></label><label>Dia da semana<select name="weekday" required><option value="">SELECIONE</option><?php foreach($days as $n=>$label):?><option value="<?=$n?>"><?=e($label)?></option><?php endforeach;?></select></label><label>Hora inicial prevista<input type="time" name="start_time"></label><label>Hora final prevista<input type="time" name="end_time"></label><label>Observação<input name="notes"></label></div><h3>Quem deve marcar presença?</h3><div class="presence-audience-grid"><label class="check area-check"><input type="checkbox" name="include_students" checked> ALUNOS</label><label class="check area-check"><input type="checkbox" name="include_instructors" checked> INSTRUTORES / AUXILIARES</label><label class="check area-check"><input type="checkbox" name="include_team"> EQUIPE BAMAB</label><label class="check area-check"><input type="checkbox" name="include_companions"> ACOMPANHANTES</label></div><h3>Alas participantes</h3><div class="instructor-area-grid"><?php foreach(enrollment_instruments() as $area):?><label class="check area-check"><input type="checkbox" name="areas[]" value="<?=e($area)?>" checked> <?=e($area)?></label><?php endforeach;?></div><button class="primary">SALVAR PROGRAMAÇÃO SEMANAL</button></form></section>
<section class="panel"><h2>Programação semanal</h2><p>Essas programações permanecem cadastradas. Em cada semana, o sistema cria automaticamente a presença com a data daquele dia quando o primeiro instrutor responsável acessar sua área.</p><div class="weekly-schedule-grid"><?php foreach($schedules as $s):$areas=attendance_schedule_areas((int)$s['id']);?><article class="<?=$s['active']?'schedule-active':'schedule-paused'?>"><div class="schedule-day"><?=e(bamab_weekday_label((int)$s['weekday']))?></div><h3><?=e($s['title'])?></h3><p><?=e($s['event_type'])?><?= $s['start_time']?' · '.e($s['start_time']):''?><?= $s['end_time']?' às '.e($s['end_time']):''?></p><small><?=e(implode(' • ',$areas))?></small><small class="schedule-audience">Presença: <?=e(implode(' · ',array_filter([(int)($s['include_students']??1)?'ALUNOS':'',(int)($s['include_instructors']??1)?'INSTRUTORES/AUX.':'',(int)($s['include_team']??0)?'EQUIPE':'',(int)($s['include_companions']??0)?'ACOMPANHANTES':''])))?></small><div class="schedule-actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_schedule"><input type="hidden" name="schedule_id" value="<?=$s['id']?>"><input type="hidden" name="active" value="<?=$s['active']?0:1?>"><button class="<?=$s['active']?'danger-soft':'activate-btn'?>"><?=$s['active']?'PAUSAR':'ATIVAR'?></button></form><?php if(is_general_admin($u)):?><form method="post" onsubmit="return confirm('Excluir esta programação semanal?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_schedule"><input type="hidden" name="schedule_id" value="<?=$s['id']?>"><button class="delete-period-btn">EXCLUIR</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$schedules):?><div class="empty-cell">Nenhuma programação semanal cadastrada.</div><?php endif;?></div></section>
<section class="panel"><div class="panel-heading-flex"><div><h2>Controles gerados hoje</h2><p><?=e(bamab_weekday_label($todayWeek))?>, <?=e(date('d/m/Y'))?>. Estes registros aparecem somente depois que um instrutor autorizado entra na área interna.</p></div><a class="small-button" href="../instrutor/login.php" target="_blank" rel="noopener noreferrer">LOGIN DOS INSTRUTORES</a></div><?php if($todayEvents):?><div class="attendance-event-list"><?php foreach($todayEvents as $ev):?><article class="<?=$ev['active']?'active-event':''?>"><div><strong><?=e($ev['title'])?></strong><small><?=e($ev['event_type'])?> · <?=e(date('d/m/Y',strtotime($ev['event_date'])))?> · Entrada: <?=$ev['entries']?> · Saída: <?=$ev['exits']?></small></div><a class="small-button" href="?event_id=<?=$ev['id']?>">ABRIR</a><a class="small-button" href="presenca_leitor.php?event_id=<?=$ev['id']?>">LEITOR GERAL</a><a class="small-button" href="presenca_relatorio.php?event_id=<?=$ev['id']?>">RELATÓRIO ALUNOS</a><a class="small-button" href="presenca_geral_relatorio.php?event_id=<?=$ev['id']?>">RELATÓRIO GERAL</a><a class="small-button" href="presenca_relatorio.php?event_id=<?=$ev['id']?>&export=xls">EXCEL</a><?php if($ev['active']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close"><input type="hidden" name="event_id" value="<?=$ev['id']?>"><button class="danger-soft">ENCERRAR DIA</button></form><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="empty-cell">Ainda não há controle gerado hoje. Ele será criado automaticamente quando um instrutor das alas programadas fizer login.</div><?php endif;?></section>
<?php if($selected&&in_array($selected['control_mode'],['ALA_DUAL','ALA_DUAL_WEEKDAY'],true)):?><section class="panel"><div class="panel-heading-flex"><div><h2><?=e($selected['title'])?></h2><p><?=e($selected['event_type'])?> · <?=e(date('d/m/Y',strtotime($selected['event_date'])))?><?= $selected['start_time']?' · '.e($selected['start_time']):''?><?= $selected['end_time']?' às '.e($selected['end_time']):''?></p></div><a class="admin-action-link" href="presenca_leitor.php?event_id=<?=$selectedId?>">LEITOR GERAL</a><a class="admin-action-link" href="presenca_relatorio.php?event_id=<?=$selectedId?>">RELATÓRIO POR ALA</a><a class="admin-action-link" href="presenca_geral_relatorio.php?event_id=<?=$selectedId?>">RELATÓRIO GERAL</a><a class="admin-action-link" href="presenca_relatorio.php?event_id=<?=$selectedId?>&export=xls">EXCEL</a></div><div class="area-control-admin-grid"><?php foreach($selectedAreas as $area):$c=attendance_area_control($selectedId,$area);$st=$pdo->prepare("SELECT COUNT(*) FROM attendance_checks WHERE event_id=? AND area=? AND person_type='ALUNO' AND check_type='ENTRADA'");$st->execute([$selectedId,$area]);$en=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM attendance_checks WHERE event_id=? AND area=? AND person_type='ALUNO' AND check_type='SAIDA'");$st->execute([$selectedId,$area]);$ex=(int)$st->fetchColumn();$inst=$pdo->prepare("SELECT i.full_name,i.preferred_name,i.role FROM instructors i JOIN instructor_areas ia ON ia.instructor_id=i.id WHERE ia.area=? AND i.active=1 ORDER BY i.role,i.full_name");$inst->execute([$area]);$people=$inst->fetchAll();?><article><div><span><?=e($area)?></span><strong><?=e(attendance_phase_label($c['phase']))?></strong></div><div class="area-counts"><b>ENTRADA <?=$en?></b><b>SAÍDA <?=$ex?></b></div><small>Responsáveis: <?=e($people?implode(', ',array_map(fn($x)=>($x['preferred_name']?:$x['full_name']).' ('.$x['role'].')',$people)):'Nenhum instrutor atribuído')?></small><?php if(is_general_admin($u)):?><form method="post" onsubmit="return confirm('Reiniciar leituras desta ala?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reset_area"><input type="hidden" name="event_id" value="<?=$selectedId?>"><input type="hidden" name="area" value="<?=e($area)?>"><button class="danger-soft">REINICIAR ALA</button></form><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
